export default function registerMemoryExtension(pi: ExtensionAPI) {
    let cachedAppendix = "";
    let maxContextTokens = 0;
    let lastRemindedAt = 0;
    let currentBaseline = 0;
    let currentStreamedChars = 0;
    let needsReminder = false;

    pi.on("session_start", async (event, ctx) => {
        const projectDir = join(ctx.cwd, ".pi", "agent", "memory");
        const userDir = getUserMemoryDirectory();

        // Ensure directories exist
        await mkdir(projectDir, { recursive: true });
        await mkdir(userDir, { recursive: true });

        const useSessionCache = process.env.PI_MEMORY_SESSION_CACHE !== "false";

        let projectMemories: MemoryMeta[];
        let userMemories: MemoryMeta[];
        let allErrors: FrontmatterParseError[];

        if (useSessionCache) {
            // Try to restore from session entries (last match)
            const entries = ctx.sessionManager.getEntries();
            let cached: CachedMemoryIndex | undefined;
            for (let i = entries.length - 1; i >= 0; i--) {
                const entry = entries[i];
                if (entry.type === "custom" && entry.customType === ENTRY_TYPE) {
                    cached = entry.data as CachedMemoryIndex;
                    break;
                }
            }

            if (cached && cached.projectDir === projectDir && cached.userDir === userDir) {
                projectMemories = cached.projectMemories;
                userMemories = cached.userMemories;
                allErrors = [];
            } else {
                const [projectResult, userResult] = await Promise.all([
                    scanMemories(projectDir),
                    scanMemories(userDir),
                ]);
                projectMemories = projectResult.memories;
                userMemories = userResult.memories;
                allErrors = [...projectResult.errors, ...userResult.errors];

                pi.appendEntry(ENTRY_TYPE, {
                    projectDir,
                    userDir,
                    projectMemories,
                    userMemories,
                } satisfies CachedMemoryIndex);
            }
        } else {
            const [projectResult, userResult] = await Promise.all([
                scanMemories(projectDir),
                scanMemories(userDir),
            ]);
            projectMemories = projectResult.memories;
            userMemories = userResult.memories;
            allErrors = [...projectResult.errors, ...userResult.errors];
        }

        if (allErrors.length > 0 && ctx.hasUI) {
            for (const error of allErrors) {
                ctx.ui.notify(`pi-memory: ${error.message}`, "warning");
            }
        }

        // Build and cache the prompt appendix
        cachedAppendix = buildPromptAppendix(projectMemories, userMemories, projectDir, userDir);

        // Remind the agent to check memories on the first turn of this session
        needsReminder = true;
    });

    pi.on("session_compact", async (_event, _ctx) => {
        // Remind the agent to check memories on the first turn after compaction
        needsReminder = true;
    });

    pi.on("agent_start", async (_event, _ctx) => {
        maxContextTokens = 0;
        currentBaseline = 0;
        currentStreamedChars = 0;
    });

    pi.on("message_start", async (event, ctx) => {
        if (event.message.role !== "assistant") return;
        const usage = ctx.getContextUsage();
        currentBaseline = usage?.tokens ?? 0;
        currentStreamedChars = 0;
        if (currentBaseline > maxContextTokens) {
            maxContextTokens = currentBaseline;
        }
    });

    pi.on("message_update", async (event, _ctx) => {
        if (event.message.role !== "assistant") return;
        const ev = event.assistantMessageEvent;
        if (ev.type === "text_delta" || ev.type === "thinking_delta") {
            currentStreamedChars += ev.delta.length;
        }
        const estimated = currentBaseline + Math.ceil(currentStreamedChars / 4);
        if (estimated > maxContextTokens) {
            maxContextTokens = estimated;
        }
    });

    pi.on("before_agent_start", async (event, _ctx) => {
        if (!cachedAppendix) return;

        let systemPrompt = event.systemPrompt;

        // Skip if already injected (e.g. sub-agent inheriting parent's prompt)
        if (systemPrompt.includes("<memory_system>")) {
            return;
        }

        const memoryBlock = `<memory_system>\n${cachedAppendix}\n</memory_system>`;
        const projectContextEnd = "</project_context>";
        const idx = systemPrompt.indexOf(projectContextEnd);
        if (idx !== -1) {
            systemPrompt =
                systemPrompt.slice(0, idx + projectContextEnd.length) +
                "\n\n" +
                memoryBlock +
                "\n" +
                systemPrompt.slice(idx + projectContextEnd.length);
        } else {
            systemPrompt = systemPrompt + "\n" + memoryBlock;
        }

        const result: {
            systemPrompt: string;
            message?: { customType: string; content: string; display: boolean };
        } = {
            systemPrompt,
        };

        if (!event.systemPromptOptions) {
            return result;
        }

        // Session-start / post-compaction reminder (always enabled)
        const sessionReminder = needsReminder;
        if (sessionReminder) {
            needsReminder = false;
        }

        // Token-threshold reminder (opt-in via env var)
        const thresholdReminderEnabled = process.env.PI_MEMORY_REMINDER === "true";
        const threshold = parseInt(process.env.PI_MEMORY_REMINDER_THRESHOLD ?? "25000", 10);
        const newTokens = maxContextTokens - lastRemindedAt;
        const thresholdTriggered = thresholdReminderEnabled && newTokens >= threshold;

        if (thresholdTriggered) {
            lastRemindedAt = maxContextTokens;
        }

        if (thresholdReminderEnabled) {
            pi.appendEntry("pi-memory:debug", {
                reminderEnabled: thresholdReminderEnabled,
                threshold,
                maxContextTokens,
                newTokens,
                lastRemindedAt,
                triggered: thresholdTriggered,
                sessionReminder,
            });
        }

        if (sessionReminder || thresholdTriggered) {
            result.message = {
                customType: "pi-memory",
                content:
                    "<memory_reminder>\nBefore starting work, consider whether any memories listed in the <memory_system> section of your system prompt are relevant to the user's request and read them if so.\n</memory_reminder>",
                display: false,
            };
        }

        return result;
    });
}

import {
    FrontmatterParseError,
    parseFrontmatter as parseGenericFrontmatter,
} from "../../common/frontmatter";

export { FrontmatterParseError } from "../../common/frontmatter";

export interface MemoryMeta {
    name: string;
    description: string;
    category?: string;
    priority?: number;
    keep_updated?: boolean;
    status?: string;
}

function scalarText(value: unknown): string | undefined {
    if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
        return String(value);
    }
    return undefined;
}

/** Parse and validate the memory-specific frontmatter schema. */
export function parseFrontmatter(content: string, filePath: string): MemoryMeta {
    const { frontmatter } = parseGenericFrontmatter(content, filePath);
    const name = scalarText(frontmatter.name);
    const description = scalarText(frontmatter.description);

    if (name === undefined) {
        throw new FrontmatterParseError(filePath, "missing required `name` field in frontmatter");
    }
    if (description === undefined) {
        throw new FrontmatterParseError(
            filePath,
            "missing required `description` field in frontmatter",
        );
    }

    const meta: MemoryMeta = { name, description };
    const category = scalarText(frontmatter.category);
    if (category !== undefined) meta.category = category;

    const priority = scalarText(frontmatter.priority);
    if (priority !== undefined) {
        const parsedPriority = parseInt(priority, 10);
        if (!Number.isNaN(parsedPriority)) meta.priority = parsedPriority;
    }

    const keepUpdated = scalarText(frontmatter.keep_updated);
    if (keepUpdated !== undefined) {
        meta.keep_updated = keepUpdated === "true" || keepUpdated === "yes";
    }

    const status = scalarText(frontmatter.status);
    if (status !== undefined) meta.status = status;

    return meta;
}

import { parseFrontmatter as parsePiFrontmatter } from "@earendil-works/pi-coding-agent";

export interface ParsedFrontmatter<T extends Record<string, unknown> = Record<string, unknown>> {
    frontmatter: T;
    body: string;
}

const MAX_FRONTMATTER_LINES = 128;

export class FrontmatterParseError extends Error {
    constructor(
        public readonly filePath: string,
        reason: string,
    ) {
        super(`${filePath}: ${reason}`);
        this.name = "FrontmatterParseError";
    }
}

function normalizeNewlines(content: string): string {
    return content.replace(/\r\n/g, "\n").replace(/\r/g, "\n");
}

function extractFrontmatter(
    content: string,
    filePath: string,
): { yaml: string; body: string } | undefined {
    const normalized = normalizeNewlines(content);
    const openingEnd = normalized.indexOf("\n");
    const openingLine = openingEnd === -1 ? normalized : normalized.slice(0, openingEnd);

    if (openingLine !== "---") {
        return undefined;
    }

    if (openingEnd === -1) {
        throw new FrontmatterParseError(
            filePath,
            "missing closing YAML frontmatter delimiter (---)",
        );
    }

    let lineStart = openingEnd + 1;
    while (lineStart <= normalized.length) {
        const lineEnd = normalized.indexOf("\n", lineStart);
        const end = lineEnd === -1 ? normalized.length : lineEnd;
        const line = normalized.slice(lineStart, end);

        if (/^---[ \t]*$/.test(line)) {
            const bodyStart = lineEnd === -1 ? normalized.length : lineEnd + 1;
            return {
                yaml: normalized.slice(openingEnd + 1, lineStart),
                body: normalized.slice(bodyStart),
            };
        }

        if (lineEnd === -1) break;
        lineStart = lineEnd + 1;
    }

    throw new FrontmatterParseError(filePath, "missing closing YAML frontmatter delimiter (---)");
}

function isRecord(value: unknown): value is Record<string, unknown> {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}

function unquoteLegacyValue(value: string): string {
    if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
    ) {
        return value.slice(1, -1);
    }
    return value;
}

/**
 * The original memory parser accepted quoted scalar values spanning multiple
 * physical lines. That is not accepted by the YAML parser used by pi, so keep
 * this narrowly scoped compatibility path for existing memory files.
 */
function parseLegacyMultilineScalars(yaml: string): Record<string, unknown> | undefined {
    const lines = yaml.split("\n");
    const fields: Record<string, unknown> = {};
    let foundLegacyScalar = false;

    for (let index = 0; index < lines.length; index++) {
        const line = lines[index].trimEnd();
        const colonIndex = line.indexOf(":");
        if (colonIndex <= 0) continue;

        const key = line.slice(0, colonIndex).trim();
        const value = line.slice(colonIndex + 1).trim();
        let quote: '"' | "'" | undefined;
        if (value.startsWith('"')) {
            quote = '"';
        } else if (value.startsWith("'")) {
            quote = "'";
        }
        if (!quote || value.endsWith(quote)) {
            fields[key] = unquoteLegacyValue(value);
            continue;
        }

        const parts = [value];
        let closed = false;
        for (index += 1; index < lines.length; index++) {
            const part = lines[index];
            parts.push(part);
            if (part.endsWith(quote)) {
                closed = true;
                break;
            }
        }
        if (!closed) return undefined;

        foundLegacyScalar = true;
        fields[key] = unquoteLegacyValue(parts.join("\n"));
    }

    return foundLegacyScalar ? fields : undefined;
}

/**
 * Parse YAML frontmatter while preserving the Markdown body.
 *
 * Files without an opening delimiter are treated as ordinary Markdown. Files
 * with an opening delimiter must have a closing delimiter and a mapping as
 * their YAML value. YAML parser failures are normalized to a project error so
 * callers can report the source file consistently.
 */
export function parseFrontmatter<T extends Record<string, unknown> = Record<string, unknown>>(
    content: string,
    filePath = "<frontmatter>",
): ParsedFrontmatter<T> {
    const extracted = extractFrontmatter(content, filePath);
    if (!extracted) {
        return { frontmatter: {} as T, body: normalizeNewlines(content) };
    }
    if (extracted.yaml.split("\n").length > MAX_FRONTMATTER_LINES) {
        throw new FrontmatterParseError(
            filePath,
            `frontmatter exceeds ${MAX_FRONTMATTER_LINES} lines, is it malformed?`,
        );
    }

    let frontmatter: unknown;
    try {
        // Reuse pi-coding-agent's YAML-backed parser. The synthetic document
        // prevents its body extraction from affecting the body we preserve.
        frontmatter = parsePiFrontmatter(`---\n${extracted.yaml}\n---\n`).frontmatter;
    } catch (error) {
        const legacy = parseLegacyMultilineScalars(extracted.yaml);
        if (legacy) {
            frontmatter = legacy;
        } else {
            const reason = error instanceof Error ? error.message : String(error);
            throw new FrontmatterParseError(filePath, `invalid YAML frontmatter: ${reason}`);
        }
    }

    if (frontmatter === null || frontmatter === undefined) {
        return { frontmatter: {} as T, body: extracted.body };
    }
    if (!isRecord(frontmatter)) {
        throw new FrontmatterParseError(filePath, "frontmatter must contain a YAML mapping");
    }

    return { frontmatter: frontmatter as T, body: extracted.body };
}

